I'm now implementing unit conversions for BNP, NT-proBNP, and Troponin, refining the script with additional range checks, and unit conversion logic for these features, alongside Urine_Specific_Gravity, with ranges and factors. I've re-examined the lab data, focusing on Patient 3. I'm building out a script for handling the mixed units, and potential unit errors.

```python
import pandas as pd
import numpy as np

def clean_value(val):
    if pd.isna(val):
        return np.nan
    if isinstance(val, str):
        val = val.replace(',', '.')
    try:
        return float(val)
    except ValueError:
        return np.nan

def convert_units(df):
    # Units and ranges (US Conventional)
    unit_data = {
        'BNP': {'range': (0, 100), 'conversions': [(1, 'mult')]},  # pg/mL, no SI conversion for this
        'NT_proBNP': {'range': (0, 125), 'conversions': [(1, 'mult')]},  # pg/mL, no SI conversion for this
        'Troponin_I': {'range': (0, 0.04), 'conversions': [(0.001, 'mult')]},  # ng/mL, SI µg/L
        'Urine_Specific_Gravity': {'range': (1.005, 1.030), 'conversions': []}
    }
    for col, data in unit_data.items():
        if col in df.columns:
            df[col] = df[col].apply(clean_value)
            for value in df[col]:
                if not pd.isna(value):
                    if value > data['range'][1]:  # High
                        df[col] = df[col].apply(lambda x: x * data['conversions'][0][0] if not pd.isna(x) and x > data['range'][1] else x)
                    elif value < data['range'][0]:  # Low
                        df[col] = df[col].apply(lambda x: x * data['conversions'][0][0] if not pd.isna(x) and x < data['range'][0] else x)

    return df
```
